def parse_expression(expr: str) -> int:
    def helper(index):
        stack = []
        num = 0
        op = '+'
        while index < len(expr):
            ch = expr[index]
            if ch.isdigit():
                num = num * 10 + int(ch)
            if ch == '(':
                num, index = helper(index + 1)
            if ch in '+-*/' or ch == ')' or index == len(expr) - 1:
                if op == '+':
                    stack.append(num)
                elif op == '*':
                    stack.append(stack.pop() * num)
                op = ch
                num = 0
                if ch == ')':
                    break
            index += 1
        return sum(stack), index
    result, _ = helper(0)
    return result

