下面这段代码实现「项目构建顺序」求解（拓扑排序），但存在一个 bug：当依赖图中存在环时，它不会报告环，而是静默返回一个只含部分项目的列表，调用方无法区分「正常完成」与「存在循环依赖」。

```python
def build_order(projects, deps):
    graph = {}
    indeg = {}
    for p in projects:
        graph[p] = []
        indeg[p] = 0
    for a, b in deps:
        graph[b].append(a)
        indeg[a] += 1
    ready = []
    for p in projects:
        if indeg[p] == 0:
            ready.append(p)
    order = []
    while len(ready) > 0:
        ready.sort()
        cur = ready.pop(0)
        order.append(cur)
        for nxt in graph[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                ready.append(nxt)
    return order
```

请修复后提交完整实现。约定：
- 参数 projects 为项目名字符串列表（无重复）；
- 参数 deps 为 [a, b] 列表，表示 a 依赖 b，因此 b 必须排在 a 之前；deps 可能为 None；
- 返回满足全部依赖的一个合法顺序（字符串列表）；当多个项目同时可执行时，取字典序最小者，以保证结果唯一；
- 若存在循环依赖（无法排完所有项目），返回 ["CYCLE"]。

tasks.reference_solution:
import heapq


def build_order(projects, deps):
    projects = list(projects or [])
    graph = {p: [] for p in projects}
    indeg = {p: 0 for p in projects}
    for a, b in (deps or []):
        if a not in graph or b not in graph:
            continue
        graph[b].append(a)
        indeg[a] += 1
    ready = [p for p in projects if indeg[p] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        cur = heapq.heappop(ready)
        order.append(cur)
        for nxt in graph[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(ready, nxt)
    if len(order) != len(projects):
        return ["CYCLE"]
    return order

class _DSU:
    def __init__(self, n):
        self._parent = list(range(n))
        self._rank = [0] * n

    def find(self, x):
        while self._parent[x] != x:
            self._parent[x] = self._parent[self._parent[x]]
            x = self._parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self._rank[ra] < self._rank[rb]:
            ra, rb = rb, ra
        self._parent[rb] = ra
        if self._rank[ra] == self._rank[rb]:
            self._rank[ra] += 1
        return True


def min_wiring_cost(n, links):
    if n <= 1:
        return 0
    dsu = _DSU(n)
    total = 0
    used = 0
    for u, v, w in sorted(links or [], key=lambda e: (e[2], e[0], e[1])):
        if dsu.union(u, v):
            total += w
            used += 1
            if used == n - 1:
                return total
    return -1

